<!DOCTYPE html>
<html lang="ko">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>롯데월드타워 3D 모델 및 설계 과정</title>
    <style>
        body {
            font-family: Arial, sans-serif;
            margin: 0;
            background-color: #f0f0f0;
        }
        #container {
            width: 80%;
            margin: 40px auto;
            text-align: center;
        }
        #model-name {
            font-size: 24px;
            font-weight: bold;
            margin-bottom: 20px;
        }
        #description {
            font-size: 18px;
            margin-bottom: 40px;
        }
        #diagrams {
            display: flex;
            flex-wrap: wrap;
            justify-content: center;
        }
        #diagrams img {
            width: 200px;
            height: 200px;
            margin: 10px;
            border: 1px solid #ddd;
            border-radius: 10px;
            box-shadow: 0 0 10px rgba(0, 0, 0, 0.1);
        }
        #3d-model {
            width: 600px;
            height: 600px;
            margin: 40px auto;
            border: 1px solid #ddd;
            border-radius: 10px;
            box-shadow: 0 0 10px rgba(0, 0, 0, 0.1);
        }
        #controls {
            margin-top: 20px;
        }
        #controls button {
            width: 100px;
            height: 30px;
            margin: 10px;
            border: none;
            border-radius: 10px;
            background-color: #4CAF50;
            color: #fff;
            cursor: pointer;
        }
        #controls button:hover {
            background-color: #3e8e41;
        }
    </style>
</head>
<body>
    <div id="container">
        <div id="model-name">롯데월드타워</div>
        <div id="description">
            롯데월드타워의 건축 설계 과정을 이해할 수 있도록, 설계도면과 단계별 3D 모델 및 완성된 3D 모델을 함께 보여주는 인터랙티브 웹페이지입니다.
        </div>
        <div id="diagrams">
            <img src="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAUAAAAFCAYAAACNbyblAAAAHElEQVQI12P4//8/w38GIAXDIBKE0DHxgljNBAAO9TXL0Y4OHwAAAABJRU5ErkJggg==" alt="배치도">
            <img src="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAUAAAAFCAYAAACNbyblAAAAHElEQVQI12P4//8/w38GIAXDIBKE0DHxgljNBAAO9TXL0Y4OHwAAAABJRU5ErkJggg==" alt="기준층 평면도">
            <img src="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAUAAAAFCAYAAACNbyblAAAAHElEQVQI12P4//8/w38GIAXDIBKE0DHxgljNBAAO9TXL0Y4OHwAAAABJRU5ErkJggg==" alt="입면도">
            <img src="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAUAAAAFCAYAAACNbyblAAAAHElEQVQI12P4//8/w38GIAXDIBKE0DHxgljNBAAO9TXL0Y4OHwAAAABJRU5ErkJggg==" alt="단면도">
        </div>
        <div id="3d-model"></div>
        <div id="controls">
            <button id="prev-button">이전 단계</button>
            <button id="next-button">다음 단계</button>
            <button id="reset-button">초기화</button>
        </div>
    </div>

    <script src="../runtime/three-runtime.js"></script>
    <script>
        let scene, camera, renderer, controls;
        let modelStep = 0;
        const modelSteps = [
            { name: '초기 모델', height: 100, floors: 20 },
            { name: '중간 모델', height: 300, floors: 60 },
            { name: '완성 모델', height: 555, floors: 123 }
        ];

        init();
        animate();

        function init() {
            scene = new THREE.Scene();
            camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
            renderer = new THREE.WebGLRenderer({
                canvas: document.createElement('canvas'),
                antialias: true
            });
            renderer.setSize(600, 600);
            document.getElementById('3d-model').appendChild(renderer.domElement);
            controls = new THREE.OrbitControls(camera, renderer.domElement);

            camera.position.z = 5;

            updateModel();

            document.getElementById('prev-button').addEventListener('click', prevStep);
            document.getElementById('next-button').addEventListener('click', nextStep);
            document.getElementById('reset-button').addEventListener('click', reset);
        }

        function animate() {
            requestAnimationFrame(animate);
            controls.update();
            renderer.render(scene, camera);
        }

        function prevStep() {
            modelStep = (modelStep - 1 + modelSteps.length) % modelSteps.length;
            updateModel();
        }

        function nextStep() {
            modelStep = (modelStep + 1) % modelSteps.length;
            updateModel();
        }

        function reset() {
            modelStep = 0;
            updateModel();
        }

        function updateModel() {
            scene.clear();
            const model = modelSteps[modelStep];
            const geometry = new THREE.CylinderGeometry(50, 20, model.height, 64);
            const material = new THREE.MeshBasicMaterial({ color: 0x00ff00 });
            const tower = new THREE.Mesh(geometry, material);
            scene.add(tower);
            const floors = model.floors;
            const floorHeight = model.height / floors;
            for (let i = 0; i < floors; i++) {
                const floorGeometry = new THREE.PlaneGeometry(100, 100);
                const floorMaterial = new THREE.MeshBasicMaterial({ color: 0xffffff });
                const floor = new THREE.Mesh(floorGeometry, floorMaterial);
                floor.position.y = i * floorHeight;
                scene.add(floor);
            }
        }
    </script>
</body>
</html>
